<?php
/** Images provenance workspace: explicit rights decisions, private evidence references and contextual alt suggestions; only authenticated managed images are selectable. */
declare(strict_types=1);
use DBLESSCMS\{MediaRights,ManagedFiles,Security,Icons,HttpError};
use function DBLESSCMS\e;
/** Translate private Images controls; receive key, return plain text without effects. */
$t=static fn(string $key):string=>$context->language->text('fm.'.$key);
$rights=new MediaRights($context->store);$snapshot=$rights->repository()->read();$scope=$_GET['scope']??'public';$path=$_GET['path']??'';if(!is_string($scope)||!is_string($path))throw new HttpError(422,'Invalid media selection.','fm.error.rights');
$file=$path!==''?(new ManagedFiles($context,$scope))->describe($path):null;$record=$file!==null?$rights->find($scope,$file['root'],$path):null;
$values=$record??['author'=>'','source'=>'','license'=>'unknown','licenseUrl'=>'','credit'=>'','evidence'=>'','altSuggestion'=>'','review'=>'unreviewed','derivativesAllowed'=>false];$changed=$record!==null&&!hash_equals($record['sha256'],$file['sha256']);if($changed)$values['review']='unreviewed';
?>
<div class="fm-rights" data-fm-rights><p class="notice"><?= e($t('rightsHelp')) ?></p><p role="alert" tabindex="-1" data-rights-status hidden></p>
<?php if($file!==null): ?>
<?php if($changed): ?><p class="notice error"><?= e($t('rightsChanged')) ?></p><?php endif; ?>
<form method="post" action="<?= e($context->url('rights-save')) ?>" data-rights-form><input type="hidden" name="csrf_token" value="<?= e(Security::token()) ?>"><input type="hidden" name="scope" value="<?= e($scope) ?>"><input type="hidden" name="path" value="<?= e($path) ?>"><input type="hidden" name="rights_revision" value="<?= e($snapshot['revision']) ?>"><input type="hidden" name="registry_revision" value="<?= e($context->revision) ?>"><input type="hidden" name="file_revision" value="<?= e($file['sha256']) ?>">
<section class="panel"><h2><?= e($t('metadata')) ?></h2><p><strong><?= e($file['scope'].' / '.($file['root']!==''?$file['root'].'/':'').$file['path']) ?></strong></p><div class="field-grid">
<?php foreach(['author','source','licenseUrl','credit','evidence','altSuggestion'] as $key): ?><label class="<?= in_array($key,['credit','evidence','altSuggestion'],true)?'wide':'' ?>"><?= e($t($key)) ?><input name="<?= e($key) ?>" maxlength="<?= in_array($key,['source','licenseUrl'],true)?2048:1000 ?>" value="<?= e($values[$key]) ?>"></label><?php endforeach; ?>
<label><?= e($t('license')) ?><select name="license"><?php foreach(['unknown','owned','permission','cc0','cc-by','cc-by-sa','other'] as $license): ?><option value="<?= e($license) ?>" <?= $values['license']===$license?'selected':'' ?>><?= e($t('license.'.str_replace('-','_',$license))) ?></option><?php endforeach; ?></select></label>
<label><?= e($t('review')) ?><select name="review"><?php foreach(['unreviewed','approved','restricted'] as $review): ?><option value="<?= e($review) ?>" <?= $values['review']===$review?'selected':'' ?>><?= e($t('review.'.$review)) ?></option><?php endforeach; ?></select></label><label class="check-option"><input type="checkbox" name="derivativesAllowed" value="1" <?= $values['derivativesAllowed']?'checked':'' ?>><?= e($t('derivativesAllowed')) ?></label></div></section><div class="savebar"><a href="<?= e($context->base.'/cms-admin/?view=plugin-panel&plugin=files-manager&route=rights') ?>"><?= e($t('rights')) ?></a><button type="submit" class="button-primary" title="<?= e($t('saveRights')) ?>" aria-label="<?= e($t('saveRights')) ?>"><?= Icons::svg('confirm',$context->base) ?></button></div></form>
<?php if($scope==='private'&&$record!==null): ?><section class="panel"><h2><?= e($t('publishCopy')) ?></h2><p><?= e($t('publishCopyHelp')) ?></p><form method="post" action="<?= e($context->url('rights-copy')) ?>" data-rights-form><input type="hidden" name="csrf_token" value="<?= e(Security::token()) ?>"><input type="hidden" name="scope" value="private"><input type="hidden" name="path" value="<?= e($path) ?>"><input type="hidden" name="rights_revision" value="<?= e($snapshot['revision']) ?>"><input type="hidden" name="registry_revision" value="<?= e($context->revision) ?>"><input type="hidden" name="file_revision" value="<?= e($file['sha256']) ?>"><label><?= e($t('publicCopyName')) ?><input name="name" maxlength="120" required value="<?= e(basename($path)) ?>"></label><button type="submit" class="button-secondary" title="<?= e($t('publishCopy')) ?>" aria-label="<?= e($t('publishCopy')) ?>" <?= $record['review']!=='approved'||!$record['derivativesAllowed']||$changed?'disabled':'' ?>><?= Icons::svg('upload',$context->base) ?></button></form></section><?php endif; ?>
<?php else: ?>
<p><?= e($t('selectMetadata')) ?></p><section class="panel extension-panel"><div class="table-scroll"><table class="extension-table"><thead><tr><?php foreach(['name','author','license','review','actions'] as $key): ?><th scope="col"><?= e($t($key)) ?></th><?php endforeach; ?></tr></thead><tbody>
<?php foreach($snapshot['data']['assets'] as $asset): ?><tr><td data-label="<?= e($t('name')) ?>"><?= e($asset['path']) ?><small><?= e($asset['scope']) ?></small><code><?= e($asset['id']) ?></code></td><td data-label="<?= e($t('author')) ?>"><?= e($asset['author']) ?></td><td data-label="<?= e($t('license')) ?>"><?= e($asset['license']) ?></td><td data-label="<?= e($t('review')) ?>"><?= e($t('review.'.$asset['review'])) ?><?= $asset['trash']!==''?' · '.e($t('trash')):'' ?></td><td data-label="<?= e($t('actions')) ?>"><?php if($asset['trash']===''&&$asset['root']===$context->settings['uploads'][$asset['scope']]): ?><a class="icon-button" href="<?= e($context->base.'/cms-admin/?'.http_build_query(['view'=>'plugin-panel','plugin'=>'files-manager','route'=>'rights','scope'=>$asset['scope'],'path'=>$asset['path']])) ?>" title="<?= e($t('metadata')) ?>" aria-label="<?= e($t('metadata')) ?>"><?= Icons::svg('edit',$context->base) ?></a><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php if($snapshot['data']['assets']===[]): ?><p class="empty-state"><?= e($t('emptyRights')) ?></p><?php endif; ?></section><?php endif; ?></div>
